            severity: "error",
            path: displayPath(ctx, join(agentDir, "agent.ts")),
            message: `MCP connection "${perSessionConnection.name}" uses advertiseTools/auth, which only run on runtime: "local". Remove them or run the agent on the local runtime.`,
